#include <concepts>
#include <iostream>
#include <string>
#include <vector>

template <typename T>
concept HasSize = requires(T t) {
    t.size();
};

template <HasSize T>
std::string describe(const T& value) {
    return value.size() > 3 ? "big" : "small";
}

int main() {
    std::cout << describe(std::string("robot")) << "\n";
    std::cout << describe(std::string("ai")) << "\n";
    return 0;
}

