#include <ranges>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> words{"robot", "ai", "battery", "go", "sensor"};

    auto loud = words
              | std::views::filter([](const std::string& w) { return w.size() > 3; })
              | std::views::transform([](const std::string& w) {
                    std::string out = w;
                    for (char& c : out) {
                        c = static_cast<char>(std::toupper(c));
                    }
                    return out;
                });

    for (const auto& w : loud) {
        std::cout << w << " ";
    }
    std::cout << "\n";
    return 0;
}

