#include <algorithm>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

struct Task {
    std::string title;
    int priority;
    bool done = false;
};

class Planner {
public:
    void add(const std::string& title, int priority) {
        tasks_.push_back({title, priority, false});
    }

    bool complete(const std::string& title) {
        for (auto& t : tasks_) {
            if (t.title == title) {
                t.done = true;
                return true;
            }
        }
        return false;
    }

    std::optional<Task> next() const {
        const Task* best = nullptr;
        for (const auto& t : tasks_) {
            if (t.done) continue;
            if (!best || t.priority > best->priority) best = &t;
        }
        if (!best) return std::nullopt;
        return *best;
    }

    int remaining() const {
        return static_cast<int>(std::count_if(
            tasks_.begin(), tasks_.end(), [](const Task& t) { return !t.done; }));
    }

private:
    std::vector<Task> tasks_;
};

int main() {
    Planner p;
    p.add("charge", 5);
    p.add("say hello", 2);
    p.add("calibrate", 4);

    std::cout << "remaining " << p.remaining() << "\n";
    if (auto t = p.next()) std::cout << "next " << t->title << "\n";

    p.complete("charge");
    if (auto t = p.next()) std::cout << "then " << t->title << "\n";
    std::cout << "left " << p.remaining() << "\n";
    return 0;
}

